export interface Shape {
  area(): number;
}

export class Square implements Shape {
  area(): number {
    return 4;
  }
}

export class Circle implements Shape {
  area(): number {
    return 3;
  }
}

export function describe(s: Shape): string {
  return helper(s);
}

function helper(s: Shape): string {
  return String(s.area()) + suffix;
}

const suffix = " units";
